#!/usr/bin/env bash
set -euo pipefail
IFS=$'\n\t'

readonly LOG_DIR="${LOG_DIR:-/var/log/myapp}"   # default if unset
readonly TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT                        # cleanup on ANY exit

usage() { echo "usage: $0 <env>" >&2; exit 1; }
[[ $# -eq 1 ]] || usage

env="$1"
if [[ ! "$env" =~ ^(dev|stage|prod)$ ]]; then
  echo "invalid env: $env" >&2; exit 1
fi

log() { printf '%s [%s] %s\n' "$(date -Is)" "$1" "${*:2}" >&2; }

deploy() {
  local target="$1"
  log INFO "deploying to $target"
  curl -fsS --retry 3 --max-time 30 "https://$target/health" || {
    log ERROR "health check failed"; return 1
  }
}

deploy "$env"
log INFO done
